import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"架构总览","description":"StreamMUSE Clean Architecture 四层设计与数据流说明","frontmatter":{"title":"架构总览","description":"StreamMUSE Clean Architecture 四层设计与数据流说明"},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md","lastUpdated":1775717144000}'),i={name:"architecture/overview.md"};function p(r,a,o,c,l,d){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>StreamMUSE 以 <strong>Clean Architecture（洁净架构）</strong> 为设计目标，将系统划分为四个主要层次。</p><hr><h2 id="四层架构图" tabindex="-1">四层架构图 <a class="header-anchor" href="#四层架构图" aria-label="Permalink to &quot;四层架构图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              Presentation 层                        │</span></span>
<span class="line"><span>│   src/streammuse/presentation/                      │</span></span>
<span class="line"><span>│   CLI 入口，解析参数，创建所有组件                    │</span></span>
<span class="line"><span>└────────────────────┬────────────────────────────────┘</span></span>
<span class="line"><span>                     │ 创建 ApplicationConfig</span></span>
<span class="line"><span>                     ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              Application 层                         │</span></span>
<span class="line"><span>│   src/streammuse/application/                       │</span></span>
<span class="line"><span>│   配置模型、Factory 工厂、RealTimeMusicService 服务  │</span></span>
<span class="line"><span>└────────────────────┬────────────────────────────────┘</span></span>
<span class="line"><span>                     │ 服务逻辑依赖 Domain；Factory 负责装配 Infrastructure</span></span>
<span class="line"><span>                     ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              Domain 层                              │</span></span>
<span class="line"><span>│   src/streammuse/domain/                            │</span></span>
<span class="line"><span>│   MusicalEvent、Tempo、Protocol 定义、日志领域对象   │</span></span>
<span class="line"><span>└────────────────────▲────────────────────────────────┘</span></span>
<span class="line"><span>                     │ Infrastructure 实现 Domain 接口</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              Infrastructure 层                      │</span></span>
<span class="line"><span>│   src/streammuse/infrastructure/                    │</span></span>
<span class="line"><span>│   输入设备、输出 Sink、推理引擎的具体实现             │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="依赖规则" tabindex="-1">依赖规则 <a class="header-anchor" href="#依赖规则" aria-label="Permalink to &quot;依赖规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>可以依赖</th><th>不可依赖</th></tr></thead><tbody><tr><td>Presentation</td><td>Application、Domain、少量 Infrastructure 入口工具</td><td>—</td></tr><tr><td>Application</td><td>Domain、Factory 中的 Infrastructure 具体类</td><td>Presentation</td></tr><tr><td>Domain</td><td>无外部依赖</td><td>所有其他层</td></tr><tr><td>Infrastructure</td><td>Domain</td><td>Application、Presentation</td></tr></tbody></table><p><strong>核心原则</strong>：内层（Domain）完全不知道外层的存在。运行时核心服务 <code>RealTimeMusicService</code> 通过 Domain Protocol 与输入、输出、推理实现解耦。</p><hr><h2 id="数据流-从输入到输出" tabindex="-1">数据流：从输入到输出 <a class="header-anchor" href="#数据流-从输入到输出" aria-label="Permalink to &quot;数据流：从输入到输出&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant User as 用户（键盘/MIDI/MIDI文件）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Input as InputSource</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Service as RealTimeMusicService</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Engine as InferenceEngine</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Output as OutputSink</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over Service: 可选 count-in：只输出 metronome，不读正式输入，不发推理请求</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    User-&gt;&gt;Input: 按键 / MIDI 消息 / 文件事件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Input-&gt;&gt;Service: MusicalEvent(source=&quot;user&quot;)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Output: output_tick(tick, bar, beat)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Output: output_metronome_tick(...)（可选）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Output: output_event(user_event, &quot;user&quot;)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over Service: tick=0 发送已有 melody history；每拍末尾 tick 4n-1 发送下一拍请求</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Engine: generate_accompaniment(melody_events, generation_start_tick, ...)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Engine--&gt;&gt;Service: List[MusicalEvent] + TimingInfo</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Output: output_stats(round_trip_ms, ...)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service-&gt;&gt;Output: output_event(acc_event, &quot;model&quot;)</span></span></code></pre></div><p>当前 tick loop 的推理触发由音乐拍点驱动：默认 <code>ticks_per_beat=4</code> 时，tick=0 会用完整历史触发一次请求，之后在 tick=3、7、11... 发送 <code>generation_start_tick=tick+1</code> 的请求。<code>generation_interval_ticks</code> 仍会透传给 HTTP server 和推理日志，但不再是客户端主循环的触发条件。</p><hr><h2 id="三线程模型" tabindex="-1">三线程模型 <a class="header-anchor" href="#三线程模型" aria-label="Permalink to &quot;三线程模型&quot;">​</a></h2><p><code>RealTimeMusicService</code> 内部运行三个并发线程，通过队列通信：</p><table tabindex="0"><thead><tr><th>线程</th><th>职责</th><th>输入源</th><th>输出目标</th></tr></thead><tbody><tr><td><code>_input_worker</code></td><td>在正式时间线开始后读取输入，按当前 wall-clock 打 tick</td><td><code>InputSource.read_events()</code></td><td><code>_event_q</code>、<code>_melody_history</code></td></tr><tr><td><code>_tick_loop</code></td><td>执行 count-in、推进音乐时钟、调度播放、触发推理</td><td><code>_event_q</code>、<code>_inference_response_queue</code></td><td><code>OutputSink</code>、<code>_inference_request_queue</code></td></tr><tr><td><code>_inference_worker</code></td><td>latest-only 调用推理引擎，将结果放回响应队列</td><td><code>_inference_request_queue</code></td><td><code>_inference_response_queue</code>、<code>OutputSink</code></td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IW[_input_worker] --&gt;|MusicalEvent| EQ[_event_q]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IW --&gt;|append| MH[_melody_history]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    EQ --&gt; TL[_tick_loop]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MH --&gt; TL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TL --&gt;|output_tick/output_event/output_metronome_tick| OS[OutputSink]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TL --&gt;|generation_start_tick, melody_events| IRQ[_inference_request_queue]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IRQ --&gt; InfW[_inference_worker]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    InfW --&gt;|acc_events| IRSQ[_inference_response_queue]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IRSQ --&gt; TL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    InfW --&gt;|output_stats/log_inference| OS</span></span></code></pre></div><hr><h2 id="关键设计决策" tabindex="-1">关键设计决策 <a class="header-anchor" href="#关键设计决策" aria-label="Permalink to &quot;关键设计决策&quot;">​</a></h2><h3 id="protocol-而非-abc" tabindex="-1">Protocol 而非 ABC <a class="header-anchor" href="#protocol-而非-abc" aria-label="Permalink to &quot;Protocol 而非 ABC&quot;">​</a></h3><p>Domain 层使用 Python <code>Protocol</code>（structural subtyping）而非抽象基类（ABC）。好处：</p><ul><li>Infrastructure 实现类无需继承任何基类，减少耦合</li><li>便于测试时使用 mock 对象或 <code>MagicMock</code></li><li><code>InferenceEngine</code>、<code>InputSource</code>、<code>OutputSink</code> 均为 Protocol</li></ul><h3 id="不使用-asyncio" tabindex="-1">不使用 asyncio <a class="header-anchor" href="#不使用-asyncio" aria-label="Permalink to &quot;不使用 asyncio&quot;">​</a></h3><p>系统选择多线程而非 async/await，原因：</p><ul><li><code>python-rtmidi</code>、<code>pynput</code> 等外部库使用阻塞式回调，不适合 async</li><li>多线程模型更易于理解推理延迟与音乐时钟对齐关系</li><li>三线程间通过 <code>queue.Queue</code> 通信，线程安全且直接</li></ul><h3 id="log-inference-和-output-metronome-tick-是扩展能力" tabindex="-1"><code>log_inference()</code> 和 <code>output_metronome_tick()</code> 是扩展能力 <a class="header-anchor" href="#log-inference-和-output-metronome-tick-是扩展能力" aria-label="Permalink to &quot;\`log_inference()\` 和 \`output_metronome_tick()\` 是扩展能力&quot;">​</a></h3><p><code>OutputSink</code> Protocol 只定义核心输出方法。<code>log_inference()</code> 面向日志 Sink，<code>output_metronome_tick()</code> 面向 metronome / MIDI 录制扩展，服务层均通过 <code>hasattr</code> 检测后调用，避免把所有输出实现强制绑定到同一个功能集合。</p><hr><h2 id="各部分文档导航" tabindex="-1">各部分文档导航 <a class="header-anchor" href="#各部分文档导航" aria-label="Permalink to &quot;各部分文档导航&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>文档</th></tr></thead><tbody><tr><td>Domain</td><td><a href="./domain/overview.html">Domain 层总览</a></td></tr><tr><td>Application</td><td><a href="./application/overview.html">Application 层总览</a></td></tr><tr><td>Infrastructure</td><td><a href="./infrastructure/overview.html">Infrastructure 层总览</a></td></tr><tr><td>Presentation</td><td><a href="./presentation/overview.html">Presentation 层总览</a></td></tr></tbody></table>`,31)])])}const k=e(i,[["render",p]]);export{u as __pageData,k as default};
